Between Effects Model Estimates

# Prepare data
panel_data1 &lt;- panel_data %&gt;% filter(year &gt;= 2016 & year &lt;= 2021)
panel_data2 &lt;- panel_data %&gt;% filter(year &gt;= 2018 & year &lt;= 2022)

panel_data1 &lt;- pdata.frame(panel_data1, index = c("mun", "year"))
panel_data2 &lt;- pdata.frame(panel_data2, index = c("mun", "year"))

panel_data1 &lt;- panel_data1 %&gt;% mutate(PDET = as.numeric(PDET))

panel_data1_BE &lt;- panel_data1 %&gt;%
  group_by(mun) %&gt;%
  summarise(PDET = first(PDET), across(where(is.numeric), mean, na.rm = TRUE))

Warning: There was 1 warning in `summarise()`.
ℹ In argument: `across(where(is.numeric), mean, na.rm = TRUE)`.
ℹ In group 1: `mun = 5001`.
Caused by warning:
! The `...` argument of `across()` is deprecated as of dplyr 1.1.0.
Supply arguments directly to `.fns` through an anonymous function instead.

  # Previously
  across(a:b, mean, na.rm = TRUE)

  # Now
  across(a:b, \(x) mean(x, na.rm = TRUE))

panel_data2_BE &lt;- panel_data2 %&gt;%
  group_by(mun) %&gt;%
  summarise(PDET = first(PDET), across(where(is.numeric), mean, na.rm = TRUE))


# Estimate Between Effects Models
BE_uariv_members &lt;- lm(log_victims ~ log_rate_members, data = panel_data1_BE)
BE_uariv_pa &lt;- lm(log_victims ~ log_rate_pa_active_imp, data = panel_data2_BE)

BE_uariv_members_c &lt;- lm(log_victims ~ log_rate_members + PDET + PDET:log_rate_members + gestion + educacion + 
                           salud + servicios + log_added_value +  
                           community_councils_cero + indigenous_reserves_cero, 
                         data = panel_data1_BE)

BE_uariv_pa_c &lt;- lm(log_victims ~ log_rate_pa_active_imp + PDET + PDET:log_rate_pa_active_imp + gestion + educacion + 
                      salud + servicios + log_added_value  + 
                      community_councils_cero + indigenous_reserves_cero, 
                    data = panel_data2_BE)

# Robust SEs
robust_se_BE_uariv_members &lt;- vcovHC(BE_uariv_members, type = "HC0")
robust_se_BE_uariv_pa &lt;- vcovHC(BE_uariv_pa, type = "HC0")
robust_se_BE_uariv_members_c &lt;- vcovHC(BE_uariv_members_c, type = "HC0")
robust_se_BE_uariv_pa_c &lt;- vcovHC(BE_uariv_pa_c, type = "HC0")

coeftest_BE_uariv_members &lt;- coeftest(BE_uariv_members, vcov = robust_se_BE_uariv_members)
coeftest_BE_uariv_pa &lt;- coeftest(BE_uariv_pa, vcov = robust_se_BE_uariv_pa)
coeftest_BE_uariv_members_c &lt;- coeftest(BE_uariv_members_c, vcov = robust_se_BE_uariv_members_c)
coeftest_BE_uariv_pa_c &lt;- coeftest(BE_uariv_pa_c, vcov = robust_se_BE_uariv_pa_c)

# Export results
stargazer(BE_uariv_members, BE_uariv_pa, BE_uariv_members_c, BE_uariv_pa_c,
  se = list(
    sqrt(diag(robust_se_BE_uariv_members)), 
    sqrt(diag(robust_se_BE_uariv_pa)), 
    sqrt(diag(robust_se_BE_uariv_members_c)), 
    sqrt(diag(robust_se_BE_uariv_pa_c))
  ),
  type = "html",
  title = "Between Effects Models with Robust Standard Errors",
  dep.var.labels = "Victims in Conflict - UARIV",
  add.lines = list(
    c("Observations", 
      nobs(BE_uariv_members), 
      nobs(BE_uariv_pa), 
      nobs(BE_uariv_members_c), 
      nobs(BE_uariv_pa_c))
  )
)


